/* SSHSIG, the OpenSSH detached signature format, verify side.
 *
 * Why this format and not a bare Ed25519 signature: SSHSIG is what
 * `ssh-keygen -Y sign` emits and `ssh-keygen -Y verify` checks, so every
 * signature this system accepts can be produced and independently verified
 * with stock OpenSSH and no Civicsmith code at all. That is the conformance
 * doctrine applied to signing: the reference implementation is OpenSSH
 * itself, and this module must agree with it byte for byte. The test suite
 * pins fixtures generated by real ssh-keygen.
 *
 * Scope is deliberately narrow: ssh-ed25519 keys, a sha512 or sha256 inner
 * hash (sha512 is what OpenSSH emits by default), signature version 1.
 * Anything else is refused loudly rather than half-supported.
 *
 * Wire shapes, from openssh PROTOCOL.sshsig:
 *
 *   armored:   -----BEGIN SSH SIGNATURE----- base64 -----END SSH SIGNATURE-----
 *   blob:      byte[6] "SSHSIG" | uint32 version=1 | string publickey
 *              | string namespace | string reserved | string hash_algorithm
 *              | string signature
 *   publickey: string "ssh-ed25519" | string key(32)
 *   signature: string "ssh-ed25519" | string sig(64)
 *   signed:    byte[6] "SSHSIG" | string namespace | string reserved
 *              | string hash_algorithm | string H(message)
 *
 * No secrets appear anywhere in this module: it holds public keys (among them
 * RELEASE_KEYS, the one list of the keys that sign a release) and verifies.
 * Signing happens where the private key lives: in the operator's
 * browser (src/sign-release.html, served as SIGN_HTML), in stock ssh-keygen,
 * or, for a release, in the release signer on the operator's machine
 * (scripts/sign-sshsig.mjs, which no bundle reaches).
 */

import { ID_TABLE, idPattern, canonicalJson } from "./record-grammar/index.mjs";

const te = new TextEncoder();

const b64ToBytes = (b64) => {
  const bin = atob(b64.replace(/\s+/g, ""));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
};

export const bytesToB64 = (bytes) => {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
};

/* ssh wire reader: uint32 length-prefixed strings. */
class Rd {
  constructor(buf) { this.b = buf; this.o = 0; }
  bytes(n) {
    if (this.o + n > this.b.length) throw new Error("sshsig: truncated");
    const v = this.b.slice(this.o, this.o + n); this.o += n; return v;
  }
  u32() { const b = this.bytes(4); return (b[0] << 24 | b[1] << 16 | b[2] << 8 | b[3]) >>> 0; }
  str() { return this.bytes(this.u32()); }
  done() { return this.o === this.b.length; }
}

const wStr = (bytes) => {
  const out = new Uint8Array(4 + bytes.length);
  new DataView(out.buffer).setUint32(0, bytes.length);
  out.set(bytes, 4);
  return out;
};
export const cat = (...parts) => {
  const n = parts.reduce((a, p) => a + p.length, 0);
  const out = new Uint8Array(n);
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
};

/* Parse an OpenSSH public key line: "ssh-ed25519 AAAA... comment".
   Returns { keyType, raw (32 bytes), b64, comment } or throws. */
export function parsePubkeyLine(line) {
  const m = String(line || "").trim().split(/\s+/);
  if (m.length < 2) throw new Error("pubkey: not an OpenSSH public key line");
  const [keyType, b64] = m;
  if (keyType !== "ssh-ed25519") throw new Error("pubkey: only ssh-ed25519 is supported, got " + keyType);
  const blob = b64ToBytes(b64);
  const r = new Rd(blob);
  const t = new TextDecoder().decode(r.str());
  if (t !== "ssh-ed25519") throw new Error("pubkey: wire type mismatch");
  const raw = r.str();
  if (raw.length !== 32) throw new Error("pubkey: ed25519 key must be 32 bytes");
  return { keyType, raw, b64, comment: m.slice(2).join(" ") };
}

/* Build the OpenSSH wire public key blob from a raw 32-byte ed25519 key,
   and its authorized_keys base64. Used by the signer page and by tests. */
export function wirePubkey(raw) {
  return cat(wStr(te.encode("ssh-ed25519")), wStr(raw));
}

/* Accepts a key in any of the shapes it appears in this system: a bare
   authorized_keys base64 field, a full "ssh-ed25519 AAAA... comment" line,
   or an allowed_signers "principal ssh-ed25519 AAAA..." line. Returns the
   bare base64 of the wire public key, or null if it is not an ed25519 key. */
export function normalizeKey(entry) {
  const toks = String(entry || "").trim().split(/\s+/);
  const i = toks.indexOf("ssh-ed25519");
  const b64 = i >= 0 ? toks[i + 1] : (toks.length === 1 ? toks[0] : null);
  if (!b64 || !b64.startsWith("AAAA")) return null;
  try { return parsePubkeyLine("ssh-ed25519 " + b64).b64; } catch { return null; }
}

const dearmor = (text) => {
  const m = String(text || "").match(
    /-----BEGIN SSH SIGNATURE-----\s*([\s\S]*?)\s*-----END SSH SIGNATURE-----/);
  if (!m) throw new Error("sshsig: missing armor");
  return b64ToBytes(m[1]);
};

/* Parse an armored SSHSIG. Returns fields without verifying anything. */
export function parseSshsig(armored) {
  const blob = dearmor(armored);
  const r = new Rd(blob);
  const magic = new TextDecoder().decode(r.bytes(6));
  if (magic !== "SSHSIG") throw new Error("sshsig: bad magic");
  const version = r.u32();
  if (version !== 1) throw new Error("sshsig: unsupported version " + version);
  const pubkeyBlob = r.str();
  const namespace = new TextDecoder().decode(r.str());
  const reserved = r.str();
  const hashAlg = new TextDecoder().decode(r.str());
  const sigBlob = r.str();

  const pr = new Rd(pubkeyBlob);
  const keyType = new TextDecoder().decode(pr.str());
  if (keyType !== "ssh-ed25519") throw new Error("sshsig: only ssh-ed25519 keys are supported");
  const pubRaw = pr.str();
  if (pubRaw.length !== 32) throw new Error("sshsig: bad ed25519 key length");

  const sr = new Rd(sigBlob);
  const sigType = new TextDecoder().decode(sr.str());
  if (sigType !== "ssh-ed25519") throw new Error("sshsig: signature type mismatch");
  const sigRaw = sr.str();
  if (sigRaw.length !== 64) throw new Error("sshsig: bad ed25519 signature length");

  if (hashAlg !== "sha512" && hashAlg !== "sha256")
    throw new Error("sshsig: unsupported hash " + hashAlg);

  return { version, namespace, hashAlg, reserved, pubRaw, pubkeyBlob, sigRaw,
           pubB64: bytesToB64(wirePubkey(pubRaw)) };
}

/* Verify an armored SSHSIG over a message.
 *
 * message: Uint8Array of the exact signed bytes.
 * expectNamespace: required; a signature from the wrong namespace never
 *   verifies, so a release signature can never be replayed as a
 *   ratification attestation or vice versa.
 * allowedKeys: array of authorized_keys-style base64 strings (the AAAA...
 *   field for ssh-ed25519). The signature's embedded key must be on the
 *   list; SSHSIG carries its own key, so without this check any
 *   self-consistent signature would pass.
 *
 * Returns { ok:true, keyB64, namespace } or { ok:false, reason }. Never
 * throws: a message that is not bytes, or anything else unusable, is
 * MALFORMED, and an allowedKeys that is not a list allows no key.
 */
export async function verifySshsig(armored, message, expectNamespace, allowedKeys) {
  try { return await verify(armored, message, expectNamespace, allowedKeys); }
  catch (e) { return { ok: false, reason: "MALFORMED", detail: String((e && e.message) || e) }; }
}

const isBytes = (m) => m instanceof ArrayBuffer || ArrayBuffer.isView(m);

async function verify(armored, message, expectNamespace, allowedKeys) {
  let p;
  try { p = parseSshsig(armored); }
  catch (e) { return { ok: false, reason: "MALFORMED", detail: String(e.message || e) }; }
  if (!isBytes(message))
    return { ok: false, reason: "MALFORMED", detail: "sshsig: the message is not bytes" };

  if (p.namespace !== expectNamespace)
    return { ok: false, reason: "NAMESPACE", expected: expectNamespace, got: p.namespace };

  const allowed = (Array.isArray(allowedKeys) ? allowedKeys : []).map(normalizeKey).filter(Boolean);
  if (!allowed.includes(p.pubB64))
    return { ok: false, reason: "UNKNOWN_KEY", keyB64: p.pubB64 };

  const hash = await crypto.subtle.digest(p.hashAlg === "sha512" ? "SHA-512" : "SHA-256", message);
  const signed = cat(
    te.encode("SSHSIG"),
    wStr(te.encode(p.namespace)),
    wStr(p.reserved),
    wStr(te.encode(p.hashAlg)),
    wStr(new Uint8Array(hash)),
  );

  let key;
  try {
    key = await crypto.subtle.importKey("raw", p.pubRaw, { name: "Ed25519" }, false, ["verify"]);
  } catch (e) {
    return { ok: false, reason: "CRYPTO_UNAVAILABLE", detail: String(e.message || e) };
  }
  const good = await crypto.subtle.verify({ name: "Ed25519" }, key, p.sigRaw, signed);
  return good
    ? { ok: true, keyB64: p.pubB64, namespace: p.namespace }
    : { ok: false, reason: "BAD_SIGNATURE", keyB64: p.pubB64 };
}

/* The canonical statements this system signs. Centralised so the plane, the
   wizard, the signer page, and any future client all sign the same bytes.
   Each is single-line ASCII, so there is no canonicalisation to get wrong. */
export const NS_RELEASE = "bio-release";
export const NS_RATIFY = "bio-ratify";

/* Releases sign the ASSET BYTES themselves, not a statement about them, so a
   verified signature IS the integrity check and cannot diverge from one. */
export const ratifyStatement = (bundleId, bundleSha) =>
  te.encode(`bio-ratify ${bundleId} ${bundleSha}\n`);

/* ---------------------------------------------------------------- the fleet */

/* A SEPARATE NAMESPACE, so a signature over the plane asset can never be
   replayed as a signature over the fleet list, or the reverse. Domain
   separation costs one string here and cannot be retrofitted once signatures
   exist in the wild. */
export const NS_FLEET = "bio-release-fleet";

/* THE ONE PLACE THE FLEET STATEMENT IS BUILT, and the reason it is here rather
   than in the tool that signs it.
   A release carries several assets now — the plane and each fleet member — and
   ONE signature covers the SET. A signature per asset would let anyone serving
   the manifest DROP a member: every remaining signature still verifies and the
   installer silently installs less, which is D-115's "quietly doing less" with
   cryptographic cover.
   The producer (`bio-plane/scripts/release-assemble.mjs`) and the verifier (`newgroup`) must
   derive byte-identical statements from the same manifest, and they run in
   different processes on different machines months apart. If each built its own
   string, the first divergence would present as "signature invalid" on a release
   that is perfectly good — indistinguishable from an attack, and debugged by
   whoever is least equipped to. So neither builds it: both call this.
   The PLANE LINE IS PART OF THE STATEMENT on purpose. It is what makes the
   signature say "these members were built against THIS plane", which is the
   claim D-298 found unbacked when a month-old plane was nearly published beside
   fleet bundles compiled from today's plane source.
   Sorted by member, so two assemblers of the same tree emit the same bytes.

   THE SERVICE BINDINGS ARE PART OF THE STATEMENT, and that is deliberate rather
   than thorough. The installer cannot give every member the same bindings:
   `pdf-worker` declares NONE on purpose ("the narrowest binding that does the
   job" — it structurally cannot reach the record), while `agent-worker` needs
   PLANE. So the per-member binding set has to travel in the manifest, and
   anything the installer ACTS ON from the manifest must be signed or it is a
   value an attacker can choose. The targets travel as WRITTEN in the member's
   config — the phantom `bio-plane` included — and the installer substitutes the
   instance slug at upload; so what is signed is the SHAPE, and the slug can
   never come from the network. Rendering is `NAME:target`, sorted by binding
   name, comma-joined, and the `services=` key is always present so a member
   with none is stated rather than omitted. */
const renderServices = (services) => [...(services || [])]
  .map((s) => `${s.binding}:${s.service}`)
  .sort()
  .join(",");

/* A MEMBER IS NOT ALWAYS ONE FILE, and the signature has to say so.
   `ocr-worker` (CPDF-10 / IC-78) ships its bundle PLUS two upload parts — a
   tesseract wasm core and a language model, 5.95 MB between them — declared
   `external` so esbuild does not inline them and `assets` so FL-9's guard hashes
   them. An installer must upload all three or the member deploys and fails at
   runtime with no engine.
   SIGNING ONLY THE BUNDLE WOULD HAVE BEEN WORSE THAN INCOMPLETE. The engine's
   measured fidelity (CPDF-15) is a fidelity OF THOSE EXACT BYTES, and the
   provenance chain this member produces names a `cap` that rests on it — so a
   swapped model or wasm core changes what the record claims while every
   signature still verified. That is the record claiming more than it can
   support, with cryptographic cover.
   Rendered `path:type:sha256:bytes`, sorted by path, and `parts=` is always present
   so a member with none is STATED rather than omitted — absent and empty must
   not look alike, here as everywhere else in this statement. */
const renderParts = (parts) => [...(parts || [])]
  .map((p) => {
    /* IC-82 / FLEET's condition, COPY NEVER DEFAULT, enforced in the ONE
       function both the assembler and the installer run: a part whose module
       type is unstated cannot enter the statement, so neither side can sign
       or accept a fleet whose upload facts were guessed. The 3607b5c defect
       (wasm with no loader) is what an inferred type re-creates. */
    if (typeof p.type !== "string" || !p.type) {
      throw new Error(`REFUSED [PART_TYPE_UNSTATED]: part ${p.path} carries no module type; a guessed type is the 3607b5c defect re-created at install (IC-82).`);
    }
    return `${p.path}:${p.type}:${p.sha256}:${p.bytes}`;
  })
  .sort()
  .join(",");

/* `bio-release-fleet/2` (IC-82): the statement carries each member's UPLOAD
   FACTS — compatibility date + flags, and each part's module type — so a
   flipped flag or a mistyped part cannot survive under a good signature. A /1
   statement, or a manifest stripped of these facts, REFUSES here by name on
   BOTH sides (this function is the producer's serialiser AND the verifier's
   rebuild), which is the fail-closed geometry the change was accepted with.
   `flags=-` renders an EMPTY flag list — ocr-worker's deliberate, measured
   absence of nodejs_compat — distinctly from nothing at all, because absent
   and empty must not look alike, here as everywhere in this statement. */
export const fleetStatement = ({ version, plane, members }) =>
  `${NS_FLEET}/2\n`
  + `version ${version}\n`
  + `plane ${plane.sha256} ${plane.bytes} ${plane.asset}\n`
  + [...members]
      .sort((a, b) => (a.member < b.member ? -1 : a.member > b.member ? 1 : 0))
      .map((m) => {
        if (!m.compat || typeof m.compat.date !== "string" || !m.compat.date) {
          throw new Error(`REFUSED [MEMBER_COMPAT_UNSTATED]: member ${m.member} carries no compatibility_date; a defaulted date is the installer-guessing defect one layer up (IC-82, FLEET's copy-never-default condition).`);
        }
        if (!Array.isArray(m.compat.flags)) {
          throw new Error(`REFUSED [MEMBER_FLAGS_UNSTATED]: member ${m.member} carries no flags list; an empty list is a STATED fact and must arrive as [], never as absence (IC-82).`);
        }
        return `member ${m.member} ${m.sha256} ${m.bytes} ${m.asset}`
          + ` compat=${m.compat.date}+${m.compat.flags.length ? [...m.compat.flags].sort().join(",") : "-"}`
          + ` services=${renderServices(m.services)}`
          + ` parts=${renderParts(m.parts)}`;
      })
      .join("\n")
  + "\n";

/* CASE-5b / DEC-72: THE CASE DOCUMENT'S STATEMENT, and it is a SEPARATE
   statement rather than `ratifyStatement` reused with a case id in the bundle
   slot. Two reasons, and the second is the load-bearing one.

   (1) A case edition is identified by a PAIR — `(case_id, edition)` — where a
   bundle is identified by its id alone, its edition living inside the bytes. A
   statement that dropped the edition would have one signature standing for every
   edition of a case, which is the same defect EDITION_EXISTS refuses one level
   down.

   (2) AND IT IS DOMAIN SEPARATION, not decoration. `ratifyStatement` is the
   sentence a member signs over a FINDING. If a case document could be signed
   with a statement of that exact shape, a signature gathered for one act would
   verify for the other the moment an identifier collided — and case ids and
   bundle ids are both allocId-minted strings. The leading token differs, so the
   two message spaces cannot overlap no matter what the identifiers do.

   The NAMESPACE stays `bio-ratify`: it is the SSHSIG namespace this instance's
   signers already have configured, and splitting it would make every existing
   signer page and wizard wrong for an act they are perfectly entitled to
   perform. The separation is in the message, which is where a verifier looks. */
export const caseRatifyStatement = (caseId, edition, docSha) =>
  te.encode(`bio-ratify-case ${caseId} ${edition} ${docSha}\n`);

/* ------------------------------------------------------------- the notice */

/* DEC-111 (K1019, K1031): A "WORKING ON" NOTICE IS SIGNED IN ITS OWN NAMESPACE.
   A project's owner signs each revision of a notice with the same browser-held
   key that ratifies records, so the separation from a ratification has to be
   in the namespace, not only in the message: a notice is a statement to the
   whole network, and a signature gathered for it must never verify as consent
   to publish, nor the reverse, whatever the identifiers turn out to be. */
export const NS_NOTICE = "bio-working-on";

/* An opaque id, as record-core's minter draws it (its R6): `<PREFIX>-<year>-<counter>`,
   with an optional `-<slug>` tail. One token, ASCII, no space and no newline, so
   the statement below always has exactly its four fields.
   THE COUNTER IS record-grammar's, NEVER A COPY HELD HERE (R38, S0-13; K1470): the
   one id table every validator reads, so the 10,000th id of a year is accepted
   here the day it is minted there. The prefix is any run of capitals, so the
   core is read from the sequential form of `ID_TABLE`'s first sequential prefix,
   with that prefix replaced by `[A-Z]+`. If `idPattern`'s answer stops being
   `^<PREFIX>…$`, this throws at load: a drift is loud, never a silent narrowing.
   Exported so `scripts/embed-signpage.mjs` writes this same pattern into the
   signer page's copy (R42): one derivation, two places. */
const statementIdPattern = () => {
  const entry = ID_TABLE.find((e) => e.form === "sequential");
  const core = entry && idPattern(entry.prefix);
  const head = entry && `^${entry.prefix}`;
  if (!(core instanceof RegExp) || !core.source.startsWith(head) || !core.source.endsWith("$") || core.flags)
    throw new Error("sshsig: record-grammar's sequential id pattern is not ^<PREFIX>…$");
  return new RegExp(`^[A-Z]+${core.source.slice(head.length, -1)}(?:-[a-z0-9]+(?:-[a-z0-9]+)*)?$`);
};
export const OPAQUE_ID_RE = statementIdPattern();
const SHA256_HEX_RE = /^[0-9a-f]{64}$/;

/* R38: the bytes an owner signs for one revision of a notice. Unlike the
   ratification statements it REFUSES what it cannot state exactly: a notice id
   that is not an opaque id, a revision that is not a whole number from 1, or a
   digest that is not 64 lowercase hex characters throws, so no signature can be
   asked for over a statement whose fields could be read two ways. */
export const noticeStatement = (noticeId, revision, sha) => {
  if (typeof noticeId !== "string" || !OPAQUE_ID_RE.test(noticeId))
    throw new Error("noticeStatement: the notice id is not an opaque id");
  if (!Number.isSafeInteger(revision) || revision < 1)
    throw new Error("noticeStatement: the revision is not a whole number of at least 1");
  if (typeof sha !== "string" || !SHA256_HEX_RE.test(sha))
    throw new Error("noticeStatement: the digest is not 64 lowercase hex characters");
  return te.encode(`${NS_NOTICE} ${noticeId} ${revision} ${sha}\n`);
};

/* ------------------------------------------------------------- the docket */

/* DEC-116 item 6 (N520): A PUBLIC DOCKET ENTRY IS SIGNED IN ITS OWN NAMESPACE.
   The case's manager signs each entry with the same registered key that
   ratifies records and signs notices, so the separation is again in the
   namespace as well as in the message: an entry is a public, final statement
   beside a published case (a withdrawal among them), and a signature gathered
   for it must never verify as a ratification or a notice, nor the reverse. */
export const NS_DOCKET = "bio-docket";

/* R40: the bytes a manager signs for one docket entry: the case it stands
   beside, the entry's number in that case's docket, and the SHA-256 of the
   entry as it will be published. It refuses what it cannot state exactly, as
   noticeStatement does, so no signature is asked for over fields that could be
   read two ways. */
export const docketStatement = (caseId, seq, sha) => {
  if (typeof caseId !== "string" || !OPAQUE_ID_RE.test(caseId))
    throw new Error("docketStatement: the case id is not an opaque id");
  if (!Number.isSafeInteger(seq) || seq < 1)
    throw new Error("docketStatement: the entry number is not a whole number of at least 1");
  if (typeof sha !== "string" || !SHA256_HEX_RE.test(sha))
    throw new Error("docketStatement: the digest is not 64 lowercase hex characters");
  return te.encode(`${NS_DOCKET} ${caseId} ${seq} ${sha}\n`);
};

/* ---------------------------------------------------- the capture account */

/* DEC-81 item 3(c) (N530): A CAPTURING MEMBER'S ACCOUNT OF A CAPTURE, its one
   spelling. The capture module asks for the signature and the standalone case
   checker verifies it, in different processes and, for the checker, on a
   reader's machine months later; if each spelled the bytes, the first
   divergence would read as a forged account. So both call this.
   The digest is on the first line behind a fixed leading token, and the text
   follows exactly as given, newlines and all: an account is prose, so unlike
   the notice and docket statements nothing here refuses its fields, and each
   is taken as `String(…)`. The leading token is no other statement's, so an
   account is never the same signed bytes as a ratification, a case
   ratification, a notice or a docket entry. It is signed in `NS_RATIFY`, the
   namespace a member's key is already configured for; the separation is in
   the message, as it is for `caseRatifyStatement`. */
export const CAPTURE_ACCOUNT_TOKEN = "bio-capture-account";

/* R41: the bytes a capturing member signs for their account of a capture. */
export const captureAccountStatement = (captureSha, text) =>
  te.encode(`${CAPTURE_ACCOUNT_TOKEN} ${String(captureSha)}\n${String(text)}`);

/* ------------------------------------------------- the release keys (R45) */

/* N1047, K3158: THE ONE PLACE THE KEYS THAT SIGN A CIVICSMITH RELEASE ARE HELD.
   The release key and the offline recovery key, both made at Bob's signer-page
   sitting of 2026-10-12 (K2922, K2930), as public lines. A release, a fleet
   statement and a release notice are each verified against this list: the
   installer's ARMED_SIGNERS and every plane module that verifies one read it
   from here, so the code a group runs and the notice that tells it of the next
   release trust exactly the same keys, and a rotation (Distribution §10) is one
   edit, here. Frozen: no caller can add a key to what it is told to trust. */
export const RELEASE_KEYS = Object.freeze([
  "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAICiA6JRm52rE3agZAKqb/4ATA34c8jEp3Yef0KZyCe18 bio-release",
  "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIMdvnsYToN22fqksnV1gLYWEJJmQA6vMyXnThPJMm7yJ bio-release-recovery",
]);

/* ------------------------------------------ the release notice (R46–R48) */

/* N1047 (draft-updates §1–2): A RELEASE NOTICE IS SIGNED IN ITS OWN NAMESPACE.
   It is signed by the release key, the same key that signs the release and the
   fleet, so the separation has to be in the namespace: a group's Civicsmith
   acts on a notice (it tells every administrator an update is ready), and a
   signature gathered over a release asset or a fleet statement must never
   verify as one, nor a notice's as either of them. */
export const NS_RELEASE_NOTICE = "bio-release-notice";

/* The most characters (code points) each of a notice's three notes may hold.
   It bounds what is signed; how much a screen shows is the caller's. */
export const RELEASE_NOTES_MAX = 8000;

const VERSION_RE = /^(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)$/;
const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
const NOTES_KEYS = ["administrators", "members", "must_do"];

/* A calendar date that exists, judged without a clock (R26). */
const dateExists = (s) => {
  const m = DATE_RE.exec(s);
  if (!m) return false;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
  return days !== undefined && d >= 1 && d <= days;
};

const isPlainObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const codePoints = (s) => { let n = 0; for (const _ of s) n++; return n; };

/* Each field read ONCE into the copy that is judged and signed, so a getter
   cannot show the judge one value and the statement another. Answers the copy,
   or the name of the first field refused. */
function readNotice(notice) {
  if (!isPlainObject(notice)) return { field: "notice" };
  const { version, date, manifest, security, notes } = notice;
  if (typeof version !== "string" || !VERSION_RE.test(version)) return { field: "version" };
  if (typeof date !== "string" || !dateExists(date)) return { field: "date" };
  if (typeof manifest !== "string" || !SHA256_HEX_RE.test(manifest)) return { field: "manifest" };
  if (typeof security !== "boolean") return { field: "security" };
  if (!isPlainObject(notes) || Object.keys(notes).sort().join(",") !== NOTES_KEYS.join(",")) return { field: "notes" };
  const { members, administrators, must_do } = notes;
  for (const [name, text, mayBeEmpty] of [["members", members, false], ["administrators", administrators, false],
    ["must_do", must_do, true]]) {
    if (typeof text !== "string" || (!mayBeEmpty && text === "") || codePoints(text) > RELEASE_NOTES_MAX)
      return { field: `notes.${name}` };
  }
  return { copy: { version, date, manifest, security, notes: { members, administrators, must_do } } };
}

const renderNotice = (n) => te.encode(`${NS_RELEASE_NOTICE}/1\n`
  + `version ${n.version}\n`
  + `date ${n.date}\n`
  + `manifest ${n.manifest}\n`
  + `security ${n.security ? "yes" : "no"}\n`
  + `notes ${canonicalJson(n.notes)}\n`);

/* R47: the exact bytes a release notice is signed over. The notes are INSIDE
   what is signed (draft-updates §1): text a member reads as Civicsmith's own
   account of a release must be the publisher's, byte for byte, or a mirror
   could rewrite "what an administrator must do". Anything it cannot state
   exactly is refused by name before a byte is built. */
export const releaseNoticeStatement = (notice) => {
  let r;
  try { r = readNotice(notice); } catch { r = { field: "notice" }; }
  if (!r.copy) throw new Error(`REFUSED [NOTICE_FIELD]: ${r.field}`);
  return renderNotice(r.copy);
};

/* `a` higher than `b`, both R47 versions: part by part, as numbers of any size
   (no leading zeros, so the longer part is the larger, then by digits). */
const versionHigher = (a, b) => {
  const pa = a.split("."), pb = b.split(".");
  for (let i = 0; i < 3; i++) {
    if (pa[i].length !== pb[i].length) return pa[i].length > pb[i].length;
    if (pa[i] !== pb[i]) return pa[i] > pb[i];
  }
  return false;
};

const deepFreezeNotice = (c) => Object.freeze({ ...c, notes: Object.freeze({ ...c.notes }) });

/* R48: a release notice, judged as a group's Civicsmith must judge one fetched
   from the network: well formed, signed by a release key in its own namespace
   over exactly its fields, and newer than what runs. The signature is judged
   before the version, so "not newer" is only ever said of a notice the
   publisher really signed; an old notice replayed, or one naming the version
   that runs, is refused, so no one serving the feed can walk a group back.
   `allowedKeys` defaults to RELEASE_KEYS, the keys the running code carries.
   Never throws. */
export async function verifyReleaseNotice(notice, armored, running, allowedKeys = RELEASE_KEYS) {
  try {
    let r;
    try { r = readNotice(notice); } catch { r = { field: "notice" }; }
    if (!r.copy) return { ok: false, reason: "MALFORMED", field: r.field };
    if (typeof running !== "string" || !VERSION_RE.test(running)) return { ok: false, reason: "MALFORMED", field: "running" };
    const v = await verifySshsig(armored, renderNotice(r.copy), NS_RELEASE_NOTICE, allowedKeys);
    if (!v.ok) return v.reason === "MALFORMED" ? { ...v, field: "signature" } : v;
    if (!versionHigher(r.copy.version, running))
      return { ok: false, reason: "NOT_NEWER", version: r.copy.version, running };
    return { ok: true, notice: deepFreezeNotice(r.copy) };
  } catch (e) {
    return { ok: false, reason: "MALFORMED", field: "notice", detail: String((e && e.message) || e) };
  }
}
